-- ❌ WRONG: Returns 0 rows because col = NULL is UNKNOWN
SELECT * FROM users WHERE deleted_at = NULL;

-- ✅ CORRECT: Use IS NULL or IS NOT NULL
SELECT * FROM users WHERE deleted_at IS NULL;

-- ✅ NULL-Safe Equality: Treats two NULLs as equal
SELECT * FROM users WHERE status IS NOT DISTINCT FROM NULL;
